+interface SessionTokenPayload {
+  sessionId: string;
+  userId: string;
+  iat: number;
+  exp: number;
+}
+
+const SECRET = process.env.SESSION_SECRET || "dev-secret-change-in-production";
+const TOKEN_TTL_SECONDS = 15 * 60; // 15 minutes
+
+const encodeBase64 = (str: string): string => Buffer.from(str).toString("base64url");
+const decodeBase64 = (str: string): string => Buffer.from(str, "base64url").toString();
+
+export const createSessionToken = (
+  sessionId: string,
+  userId: string,
+): string => {
+  const now = Math.floor(Date.now() / 1000);
+  const payload: SessionTokenPayload = {
+    sessionId,
+    userId,
+    iat: now,
+    exp: now + TOKEN_TTL_SECONDS,
+  };
+
+  const header = encodeBase64(JSON.stringify({ alg: "HS256", typ: "JWT" }));
+  const body = encodeBase64(JSON.stringify(payload));
+  const message = `${header}.${body}`;
+
+  const signature = createHmac("sha256", SECRET)
+    .update(message)
+    .digest("base64url");
+
+  return `${message}.${signature}`;
+};
+
+export const verifySessionToken = (token: string): SessionTokenPayload | null => {
+  try {
+    const [header, body, signature] = token.split(".");
+    if (!header || !body || !signature) return null;
+
+    const message = `${header}.${body}`;
+    const expectedSignature = createHmac("sha256", SECRET)
+      .update(message)
+      .digest("base64url");
+
+    if (signature !== expectedSignature) return null;
+
+    const payload = JSON.parse(decodeBase64(body)) as SessionTokenPayload;
+    const now = Math.floor(Date.now() / 1000);
+    if (payload.exp < now) return null;
+
+    return payload;
+  } catch {
+    return null;
+  }
+};
